import json

def recover_relations(response: str, atoms: dict[str, str]) -> list:
    relations = []

    # Cause-Effect
    if "since" in response or "because" in response:
        if "1" in atoms and "2" in atoms:
            relations.append({
                "source": 1,
                "target": 2,
                "sense": "Cause-Effect",
                "coupling": "entailment",
                "strength_band": "strong"
            })

    # Evidence
    if "shows" in response or "indicates" in response or "confirms" in response:
        if "2" in atoms and "1" in atoms:
            relations.append({
                "source": 2,
                "target": 1,
                "sense": "Evidence",
                "coupling": "entailment",
                "strength_band": "moderate"
            })

    # Restatement
    if "in other words" in response or "that is" in response:
        if "5" in atoms and "6" in atoms:
            relations.append({
                "source": 5,
                "target": 6,
                "sense": "Restatement",
                "coupling": "equivalence",
                "strength_band": "strong"
            })

    # Refutation
    if "rules out" in response or "cannot be squared with" in response:
        if "10" in atoms and "12" in atoms:
            relations.append({
                "source": 10,
                "target": 12,
                "sense": "Refutation",
                "coupling": "contradiction",
                "strength_band": "strong"
            })

    # Contrast
    if "by contrast" in response or "whereas" in response or "but" in response:
        if "9" in atoms and "1" in atoms:
            relations.append({
                "source": 9,
                "target": 1,
                "sense": "Contrast",
                "coupling": "none",
                "strength_band": "moderate"
            })

    # Concession
    if "although" in response or "despite" in response or "even though" in response:
        if "13" in atoms and "1" in atoms:
            relations.append({
                "source": 13,
                "target": 1,
                "sense": "Concession",
                "coupling": "none",
                "strength_band": "weak"
            })

    # Alternative
    if "either" in response or "or" in response:
        if "9" in atoms and "1" in atoms:
            relations.append({
                "source": 9,
                "target": 1,
                "sense": "Alternative",
                "coupling": "exclusive",
                "strength_band": "strong"
            })

    # Disjunction
    if "at least one" in response or "perhaps both" in response:
        if "10" in atoms and "11" in atoms:
            relations.append({
                "source": 10,
                "target": 11,
                "sense": "Disjunction",
                "coupling": "co_necessity",
                "strength_band": "moderate"
            })

    # Precedence
    if "before" in response or "prior to" in response:
        if "5" in atoms and "6" in atoms:
            relations.append({
                "source": 5,
                "target": 6,
                "sense": "Precedence",
                "coupling": "none",
                "strength_band": "strong"
            })

    # Succession
    if "after" in response or "subsequent to" in response:
        if "6" in atoms and "5" in atoms:
            relations.append({
                "source": 6,
                "target": 5,
                "sense": "Succession",
                "coupling": "none",
                "strength_band": "strong"
            })

    return relations

response = "Adjudicating between descent and contact is a matter of asking which hypothesis accounts for the fine detail of the shared material, since resemblance by itself is never decisive. The comparative method establishes common descent by demonstrating systematic sound correspondences between languages; in other words, regular sound correspondences recurring across many lexical items are the primary evidence linguists accept for genetic relationship. Core vocabulary such as body parts, kinship terms, and low numerals is relatively resistant to borrowing. Pronouns and numerals belong to the basic layer of the lexicon, and basic vocabulary of that kind is never borrowed in any documented language. Phonological chronology supplies a further diagnostic. A word borrowed after a sound change has ceased to operate does not display the effects of that change; that is, a loanword that postdates a sound law fails to exhibit the reflex that the law produced. This has a direct and observable consequence for the shape such words take. Linguists test a shared item by reconstructing a proto-language form and checking whether both languages' forms follow from it by known sound laws — a practice that came about because a borrowed word frequently retains a phonological shape that violates the receiving language's historical sound laws. Shared material, however, need not point to shared ancestry at all. The term Sprachbund designates a set of geographically contiguous languages that share structural features without descending from a recent common ancestor. That such configurations are real is shown by the Balkans, where Albanian, Romanian, and Bulgarian each belong to a different branch of Indo-European, a distribution that rules out any account deriving the group as a whole from one recent shared branch. Albanian, Romanian, and Bulgarian all place the definite article after the noun. The languages of the Balkan Sprachbund all descend from a single Indo-European branch called Paleo-Balkan. Documented historical bilingualism between two speech communities supports a contact explanation for a shared feature, and the centuries of bilingualism recorded across Balkan communities are what establish the article-placement pattern described just above. The dispute is thus resolved by the convergence of criteria rather than by any one of them: reconstructed correspondences that hold across the lexicon without residue favour descent, while irregular phonological shape, a tight areal distribution, and an attested history of bilingual speakers favour transmission across a language boundary."
